ALTER TABLE public.scripts ADD COLUMN company text;

DROP POLICY IF EXISTS scripts_read_authenticated ON public.scripts;
CREATE POLICY scripts_read_authenticated ON public.scripts FOR SELECT TO authenticated
  USING (company IS NULL OR public.effective_plan(auth.uid()) = 'business' OR public.has_role(auth.uid(), 'admin'));

CREATE OR REPLACE FUNCTION public.company_script_teasers()
RETURNS TABLE(id uuid, title text, category text, company text, sort_order integer)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT s.id, s.title, s.category, s.company, s.sort_order FROM public.scripts s
  WHERE s.company IS NOT NULL AND auth.uid() IS NOT NULL ORDER BY s.sort_order
$$;
REVOKE ALL ON FUNCTION public.company_script_teasers() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.company_script_teasers() TO authenticated;

INSERT INTO public.scripts (title, category, content, sort_order, company) VALUES
('Longrich — Premier contact (ami ou famille)', 'Premier contact', E'Salut [Prénom], j''espère que tu vas bien ! Ça fait un moment qu''on ne s''est pas parlé. Je voulais te dire que depuis quelques semaines j''utilise des produits Longrich au quotidien, notamment [Produit], et j''en suis content. Je ne veux rien te forcer : je pensais simplement à toi parce que tu prends soin de ta maison et de ta famille. Si un jour tu es curieux, je peux te montrer ce que j''utilise, sans engagement. Et sinon, donne-moi surtout de tes nouvelles ! [Ton prénom]', 101, 'Longrich'),
('Longrich — Premier contact (réseau social)', 'Premier contact', E'Bonjour [Prénom], j''ai vu ta publication et j''ai apprécié ta façon de parler de ton quotidien. Je me présente : [Ton prénom], je partage des produits Longrich que j''utilise moi-même, comme [Produit]. Je ne t''écris pas pour te vendre quelque chose tout de suite. Je voulais juste savoir si tu es ouvert(e) à découvrir de nouveaux produits pour la maison ou le soin personnel. Si ce n''est pas le cas, aucun souci, je te souhaite une très belle journée !', 102, 'Longrich'),
('Longrich — Présenter un produit simplement', 'Premier contact', E'[Prénom], voici simplement ce que j''aime avec [Produit] de Longrich : je l''utilise régulièrement, il est pratique et il s''intègre bien dans ma routine. Je ne vais pas te dire qu''il règle tous les problèmes, ce n''est pas un médicament et il ne remplace pas l''avis d''un professionnel de santé. C''est un produit du quotidien, et chacun a son propre ressenti. Si tu veux, je peux t''envoyer la fiche produit officielle avec la composition et le prix, et tu décides tranquillement. [Ton prénom]', 103, 'Longrich'),
('Longrich — Inviter à une démonstration', 'Invitation', E'Coucou [Prénom] ! Je fais une petite démonstration des produits Longrich, dont [Produit], ce [jour] à [heure]. C''est court, environ 30 minutes, détendu, et tu peux poser toutes tes questions. Tu n''as rien à acheter et rien à préparer, juste venir avec ta curiosité. Tu peux aussi venir avec une amie si tu veux. Est-ce que ce créneau te convient, ou tu préfères que je t''en propose un autre ? [Ton prénom]', 104, 'Longrich'),
('Longrich — Relance après 48 h sans réponse', 'Relance', E'Re-bonjour [Prénom], je reviens vers toi suite à mon message d''avant-hier au sujet de [Produit] de Longrich. Je sais qu''on est tous très occupés, donc pas de pression. Je voulais juste savoir si tu avais eu le temps d''y jeter un œil. Si ça ne t''intéresse pas pour le moment, tu peux me le dire franchement, je ne le prendrai pas mal du tout et je ne te relancerai pas. Belle journée à toi ! [Ton prénom]', 105, 'Longrich'),
('Longrich — Relance après une présentation', 'Relance', E'Merci encore [Prénom] d''avoir pris le temps de suivre la présentation Longrich. Je voulais savoir ce que tu en as retenu et s''il te reste des questions, sur [Produit] ou sur le fonctionnement de l''activité. Prends le temps qu''il te faut pour réfléchir, il n''y a aucune urgence. Si tu préfères, on peut s''appeler 10 minutes cette semaine pour en parler tranquillement. Dis-moi ce qui t''arrange. [Ton prénom]', 106, 'Longrich'),
('Longrich — Objection « je n''ai pas d''argent »', 'Objections', E'Je te comprends tout à fait [Prénom], et c''est normal de faire attention à son budget, surtout en ce moment. Je ne veux surtout pas que tu dépenses de l''argent que tu n''as pas. On peut simplement rester en contact, et quand ce sera le bon moment pour toi, tu pourras regarder [Produit] tranquillement. Est-ce que c''est le prix qui te bloque, ou plutôt le fait de ne pas encore savoir si le produit te convient ? [Ton prénom]', 107, 'Longrich'),
('Longrich — Objection « c''est une pyramide ? »', 'Objections', E'Bonne question [Prénom], et tu as raison de la poser. Une pyramide illégale rémunère surtout le recrutement, sans vrais produits. Avec Longrich, l''activité repose sur la vente de produits réels comme [Produit], utilisés par des clients. Je préfère être honnête : comme toute activité commerciale, les résultats dépendent du travail de chacun et rien n''est garanti. Je peux te montrer les informations officielles de l''entreprise pour que tu te fasses ta propre opinion. [Ton prénom]', 108, 'Longrich'),
('Longrich — Bienvenue à une nouvelle recrue', 'Suivi d’équipe', E'Bienvenue dans l''équipe [Prénom] ! Je suis vraiment content(e) de t''accompagner avec Longrich. Pour bien démarrer, commence par découvrir les produits que tu utilises toi-même, comme [Produit], et note 10 personnes de ton entourage avec qui tu aimerais simplement en parler. On avance à ton rythme, sans pression. Je te propose un appel cette semaine pour faire le point ensemble. Quel jour t''arrange le mieux ? [Ton prénom]', 109, 'Longrich'),
('Longrich — Animation d''équipe (rappel de la semaine)', 'Suivi d’équipe', E'Bonjour l''équipe ! Petit rappel pour bien démarrer la semaine : 1) prenons des nouvelles de 5 contacts, sans parler business si ce n''est pas le moment ; 2) partageons une expérience vraie avec [Produit] ; 3) relançons poliment ceux qui avaient demandé des informations. Restons honnêtes : pas de promesses de santé ni de gains. Notre rendez-vous d''équipe est le [jour] à [heure]. Partagez vos questions ici, on avance ensemble ! [Ton prénom]', 110, 'Longrich');